/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_POLICY_COINSURANCE
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_POLICY   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 2 emitted of 2 (one per source view AND run)
   runs        : 1 -- opus_health_delta3
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_POLICY_HK
   hashdiff    : SAT_POLICY_COINSURANCE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , CO_INS_TYPE as CO_INSURANCE_ARRANGEMENT_TYPE
        , cast(null as varchar) as CO_INSURANCE_DETAILS_TEXT
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as CO_INSURANCE_ARRANGEMENT_TYPE
        , COINS_DTLS as CO_INSURANCE_DETAILS_TEXT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CO_INSURANCE_ARRANGEMENT_TYPE end) as CO_INSURANCE_ARRANGEMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CO_INSURANCE_DETAILS_TEXT end) as CO_INSURANCE_DETAILS_TEXT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when CO_INSURANCE_ARRANGEMENT_TYPE is not null or CO_INSURANCE_DETAILS_TEXT is not null
                     then md5(upper(coalesce(cast(CO_INSURANCE_ARRANGEMENT_TYPE as varchar), '') || '|' || coalesce(cast(CO_INSURANCE_DETAILS_TEXT as varchar), '')))
                end as SAT_POLICY_COINSURANCE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_COINSURANCE_HASHDIFF is not null
